def minPath(grid, k):
    n = len(grid)
    if k == 1:
        return [min(min(row) for row in grid)]

    # Find position of 1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start = (i, j)
                break

    # BFS to find lexicographically smallest path of length k
    from collections import deque
    q = deque()
    q.append((start[0], start[1], [1]))
    visited = {}

    while q:
        i, j, path = q.popleft()
        if len(path) == k:
            return path

        # Generate neighbors sorted by value
        neighbors = []
        for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
            ni, nj = i+di, j+dj
            if 0 <= ni < n and 0 <= nj < n:
                neighbors.append((grid[ni][nj], ni, nj))
        neighbors.sort()

        for val, ni, nj in neighbors:
            new_path = path + [val]
            state = (ni, nj, len(new_path))
            if state not in visited or visited[state] > new_path:
                visited[state] = new_path
                q.append((ni, nj, new_path))

    return []

